import * as THREE from 'three';

export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const makeMat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
export function box(parent,name,pos,size,mat){const o=new THREE.Mesh(new THREE.BoxGeometry(...size),mat);o.name=name;o.position.set(...pos);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
export function cyl(parent,pos,r,h,mat,segments=12){const o=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,segments),mat);o.position.set(...pos);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
export function sphere(parent,pos,r,mat,segments=12){const o=new THREE.Mesh(new THREE.SphereGeometry(r,segments,segments),mat);o.position.set(...pos);o.castShadow=true;parent.add(o);return o;}
const mats={
 asphalt:makeMat('#343b45'),sidewalk:makeMat('#b5b4aa'),line:makeMat('#e9d885'),concrete:makeMat('#d4cfc5'),
 navy:makeMat('#162e4b'),navy2:makeMat('#233e60'),white:makeMat('#f5f2e9'),skin:makeMat('#efc7a8'),hair:makeMat('#201c20'),
 black:makeMat('#1b1b22'),gold:makeMat('#deb86c',.35,.35),glass:makeMat('#62a5b7',.3,.15),window:makeMat('#91c7d0',.38,.1),
 red:makeMat('#e46d63'),green:makeMat('#58b48e'),blue:makeMat('#547ca7'),sand:makeMat('#d6bf8c'),water:makeMat('#438f9a',.26,.15),
 leaf:makeMat('#477c62'),trunk:makeMat('#76553b'),pavement:makeMat('#aeb6b7')};

export function createWorld(scene){
 scene.background=new THREE.Color('#a9c5d1');scene.fog=new THREE.Fog('#a9c5d1',58,148);
 const hemi=new THREE.HemisphereLight('#d9efff','#776e61',2.05);scene.add(hemi);
 const sun=new THREE.DirectionalLight('#fff0d6',3.15);sun.position.set(-35,60,-20);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=90;sun.shadow.camera.bottom=-90;sun.shadow.bias=-.0002;scene.add(sun);
 const ground=box(scene,'city ground',[0,-.17,0],[150,.3,150],makeMat('#97a393'));ground.receiveShadow=true;
 // Seoul-inspired paved streets, crosswalks, and small plaza
 box(scene,'main road',[0,-.005,0],[13,.08,128],mats.asphalt);box(scene,'cross road',[0,0,-13],[130,.08,11],mats.asphalt);
 for(const x of [-7.3,7.3])box(scene,'sidewalk',[x,.04,0],[2.5,.18,128],mats.sidewalk);
 for(const z of [-19, -7])box(scene,'cross sidewalk',[0,.04,z],[130,.18,1.8],mats.sidewalk);
 for(let z=-57;z<60;z+=7){box(scene,'lane dash',[0,.055,z],[.12,.025,3.3],mats.line)}
 // zebra stripes at the central crossing
 for(let x=-5.3;x<=5.4;x+=1.35)box(scene,'crosswalk stripe',[x,.062,-13],[.75,.026,4.7],mats.white);
 // side lanes through the neighborhood
 for(const x of [-42,42]){box(scene,'side street',[x,0,0],[8,.08,130],mats.asphalt);for(const z of [-6.5,6.5])box(scene,'side walk',[x+Math.sign(x)*5.3,.04,0],[2,.16,130],mats.sidewalk)}
 // far cross street
 box(scene,'north road',[0,0,42],[125,.08,9],mats.asphalt);
 // beach and water at the south edge
 box(scene,'beach sand',[0,-.005,62],[150,.12,22],mats.sand);box(scene,'sea',[0,-.1,80],[150,.25,20],mats.water);
 // waves as foamy strips
 for(let z=70;z<81;z+=3.5){const wave=box(scene,'wave',[0,.035,z],[150,.025,.13],makeMat('#d6e5d7',.35));wave.material.transparent=true;wave.material.opacity=.45}
 // blocks of shops and apartments, randomized facade color with repeatable seed
 let seed=12;const rand=()=>{seed=(seed*16807)%2147483647;return (seed-1)/2147483646};
 const facade=['#d9bfa5','#d6d5ca','#b9c9c8','#cfaaa0','#d3c7ac','#bec9d5'].map(c=>makeMat(c));
 const addBuilding=(x,z,w,d,h,kind='apt')=>{
  const color=facade[Math.floor(rand()*facade.length)];const b=box(scene,'building',[x,h/2,z],[w,h,d],color);b.castShadow=true;
  box(scene,'roof ledge',[x,h+.12,z],[w+.35,.25,d+.35],makeMat('#8a8278'));
  if(kind==='shop'){
   box(scene,'shop fascia',[x,2.65,z+d/2+.04],[w-.2,.78,.13],makeMat(['#be6d68','#658ca0','#617d6e','#dbad59'][Math.floor(rand()*4)]));
   box(scene,'shop window',[x,1.35,z+d/2+.055],[w-.55,1.55,.09],mats.glass);
   for(let xx=x-w/2+.12;xx<x+w/2;xx+=.7)box(scene,'shop frame',[xx,1.4,z+d/2+.12],[.08,1.7,.1],makeMat('#f0dcb9'));
   box(scene,'shop door',[x+w*.31,1.18,z+d/2+.13],[.65,2.1,.12],makeMat('#6a7676'));
   const sign=box(scene,'sign',[x,3.05,z+d/2+.13],[w*.83,.45,.08],makeMat('#f1debb'));sign.userData.sign=true;
  }else{
   for(let floor=1;floor<h/3;floor++)for(let col=-1;col<=1;col++){
    const xx=x+col*w*.27, yy=floor*2.7;
    box(scene,'window',[xx,yy,z+d/2+.035],[w*.18,1.3,.08],rand()>.5?mats.window:makeMat('#778995'));
    box(scene,'window sill',[xx,yy-.73,z+d/2+.09],[w*.21,.09,.13],mats.white);
   }
   for(let floor=1;floor<h/3;floor++)box(scene,'balcony rail',[x, floor*2.7-.85,z+d/2+.2],[w*.78,.08,.28],mats.black);
  }
  return b;
 };
 // blocks: stores along the avenue, homes and cafes in walkable grid
 for(const z of [-49,-34,-1,15,32])for(const x of [-27,-15,15,27])addBuilding(x,z,10,10,10+rand()*12,Math.abs(x)===15&&z<32?'shop':'apt');
 for(const z of [-48,-32,1,16,31])for(const x of [-58,-46,46,58])addBuilding(x,z,10,11,14+rand()*15,'apt');
 for(const x of [-24,-12,12,24])addBuilding(x,49,10,8,10+rand()*8,'shop');
 // Make the boutique unmistakable: gold canopy and a glowing sign
 box(scene,'boutique awning',[15,3.25,10.22],[9.2,.35,.85],makeMat('#b78656'));
 box(scene,'boutique sign',[15,3.85,10.35],[8.2,.55,.18],makeMat('#f0dcb5'));
 // lamp posts and warm lights
 const lampMat=makeMat('#343a40',.35,.45), glow=new THREE.MeshStandardMaterial({color:'#fff0c1',emissive:'#ffbf69',emissiveIntensity:2});
 for(const [x,z] of [[-9,-34],[9,-34],[-9,-1],[9,-1],[-9,28],[9,28],[-39,-23],[39,-23],[-39,21],[39,21],[-9,49],[9,49]]){
  cyl(scene,[x,2.6,z],.085,5.2,lampMat);const arm=box(scene,'lamp arm',[x+Math.sign(x)*.55,5.05,z],[1.2,.08,.08],lampMat);sphere(scene,[x+Math.sign(x)*1.05,4.95,z],.2,glow);
 }
 // tree-lined sidewalks with planters
 for(const [x,z] of [[-9,-47],[9,-47],[-9,-25],[9,-25],[-9,10],[9,10],[-9,35],[9,35],[-38,-10],[38,-10],[-38,35],[38,35],[-28,44],[-15,44],[15,44],[28,44]]){
  box(scene,'planter',[x,.26,z],[1.5,.5,1.5],makeMat('#8f8878'));cyl(scene,[x,.9,z],.18,1.25,mats.trunk,8);sphere(scene,[x,1.75,z],.92,mats.leaf,10);
 }
 // city details: benches, bollards, hydrant, bus stop and street sign
 for(const z of [-23,-2,22,44]){box(scene,'bench seat',[-10,.55,z],[2,.18,.55],makeMat('#866849'));for(const x of [-10.7,-9.3])box(scene,'bench leg',[x,.27,z],[.12,.55,.12],lampMat)}
 box(scene,'bus stop post',[10,.8,-26],[.16,1.6,.16],lampMat);box(scene,'bus stop sign',[10,1.7,-26],[.75,.7,.1],makeMat('#64a7b0'));
 for(const x of [-8.7,8.7])for(const z of [-16,-10])cyl(scene,[x,.42,z],.2,.8,makeMat('#ddbb72'));
 // beach palms
 for(const x of [-48,-32,-16,16,32,48]){cyl(scene,[x,2,63],.22,4,mats.trunk,8);for(let i=0;i<5;i++){const leaf=box(scene,'palm frond',[x+Math.cos(i*1.25)*1.4,4.1,63+Math.sin(i*1.25)*1.4],[2.3,.12,.35],mats.leaf);leaf.rotation.y=i*1.25;leaf.rotation.z=-.25}}
 // Boutique and station location markers
 const marker=(x,z,color)=>{const ring=new THREE.Mesh(new THREE.RingGeometry(1.0,1.2,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.17,z);scene.add(ring);return ring};
 return {mats,addBuilding,markers:[marker(15,8,'#f5cb70'),marker(-5,-13,'#6de0bd')],update(t){this.markers.forEach((m,i)=>{m.position.y=.18+Math.sin(t*2+i)*.12;m.rotation.z=t*.35})}};
}

export function createOfficer(scene){
 const root=new THREE.Group();root.position.set(0,0,0);scene.add(root);
 const rig=new THREE.Group();root.add(rig);
 const uniform=makeMat('#1d3655'), trim=makeMat('#b7c8d6'),skin=makeMat('#efc7a8'),hair=makeMat('#211b22'),shirt=makeMat('#f7f5ef'),gold=makeMat('#e2bd73',.35,.3),black=makeMat('#171921'),lip=makeMat('#be7775');
 // proportions: adult, stylized realistic proportions, fully uniformed
 const torso=box(rig,'uniform torso',[0,1.28,0],[.67,.76,.35],uniform);torso.castShadow=true;
 box(rig,'white shirt',[0,1.43,.19],[.24,.49,.035],shirt);
 box(rig,'belt',[0,.91,0],[.69,.105,.38],black);box(rig,'badge',[-.2,1.56,.19],[.1,.15,.035],gold);
 box(rig,'radio',[.28,1.1,.2],[.12,.18,.1],black);
 const neck=cyl(rig,[0,1.78,0],.13,.22,skin);neck.castShadow=true;
 const head=sphere(rig,[0,2.02,0],.31,skin,20);head.scale.set(.86,1.1,.82);
 // hair cap and bob, with bangs framing face
 const cap=sphere(rig,[0,2.16,-.045],.31,hair,18);cap.scale.set(.92,.9,.9);
 sphere(rig,[-.27,1.99,0],.095,hair,10).scale.set(.8,1.25,.78);sphere(rig,[.27,1.99,0],.095,hair,10).scale.set(.8,1.25,.78);
 const fringe=sphere(rig,[0,2.24,.15],.22,hair,12);fringe.scale.set(1.18,.38,.55);
 // friendly face details
 for(const x of [-.105,.105]){sphere(rig,[x,2.06,.247],.027,black,8);sphere(rig,[x-.01,2.073,.268],.008,makeMat('#fffefa'),6)}
 box(rig,'nose',[0,1.99,.285],[.05,.075,.05],skin);
 const mouth=box(rig,'smile',[0,1.91,.263],[.1,.018,.018],lip);
 // cap with police mark
 const hat=box(rig,'police cap',[0,2.39,-.015],[.52,.14,.42],uniform);hat.rotation.x=-.05;box(rig,'cap brim',[0,2.32,.19],[.48,.045,.24],uniform);sphere(rig,[0,2.4,.205],.045,gold,8);
 // arms and articulated legs
 const arms=[],legs=[];
 for(const x of [-.43,.43]){const pivot=new THREE.Group();pivot.position.set(x,1.57,0);rig.add(pivot);cyl(pivot,[0,-.28,0],.12,.57,uniform);sphere(pivot,[0,-.59,.015],.115,skin,10);arms.push(pivot)}
 for(const x of [-.19,.19]){const pivot=new THREE.Group();pivot.position.set(x,.91,0);rig.add(pivot);box(pivot,'trouser leg',[0,-.33,0],[.23,.7,.28],uniform);box(pivot,'ankle',[0,-.68,.04],[.18,.12,.23],skin);const shoe=box(pivot,'black ballet flat',[0,-.75,.1],[.22,.13,.39],black);shoe.castShadow=true;legs.push(pivot)}
 // optional garment props anchored to rig
 return {root,rig,legs,arms,torso,head,updateWalk(time,speed){const amount=Math.min(1,speed/3);legs[0].rotation.x=Math.sin(time*9)*.58*amount;legs[1].rotation.x=-Math.sin(time*9)*.58*amount;arms[0].rotation.x=-Math.sin(time*9)*.34*amount;arms[1].rotation.x=Math.sin(time*9)*.34*amount;rig.position.y=speed>.1?Math.abs(Math.sin(time*9))*.035:0;},setShoes(type){legs.forEach(l=>{const shoe=l.children.find(o=>o.name==='black ballet flat');if(!shoe)return;shoe.scale.set(type==='heels'?.85:1,type==='barefoot'?.35:.8,type==='heels'?.92:1);shoe.material=type==='heels'?makeMat('#17151c',.35):type==='barefoot'?skin:makeMat('#17151c',.45)})},setTights(color){legs.forEach(l=>{let tight=l.children.find(o=>o.name==='tights');if(tight)l.remove(tight);if(color){tight=box(l,'tights',[0,-.34,-.16],[.235,.68,.035],makeMat(color,.55));tight.castShadow=false}})}};
}

export function createPerson(scene,x,z,kind,index){
 const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 const colors=kind==='criminal'?['#7c3d3f','#484457','#675034']:['#67979a','#bd826e','#656e91','#a9895b','#73906e'];
 const top=makeMat(kind==='criminal'?colors[index%colors.length]:colors[index%colors.length]), skin=makeMat('#d9ae91'),hair=makeMat(kind==='criminal'?'#27232b':'#3e2d27'),pants=makeMat(kind==='criminal'?'#302e36':'#3d4c59'),shoemat=makeMat('#272a31');
 cyl(g,[0,1.1,0],.23,.74,top,10);const head=sphere(g,[0,1.68,0],.19,skin,12);head.scale.set(.86,1.1,.9);sphere(g,[0,1.78,-.03],.19,hair,10).scale.set(1,.65,1);
 for(const s of [-1,1]){cyl(g,[s*.12,.48,0],.075,.6,pants,8);box(g,'shoe',[s*.12,.11,.08],[.16,.13,.28],shoemat)}
 sphere(g,[0,1.15,.24],.045,makeMat('#e9d6c1'),8);
 if(kind==='criminal'){box(g,'hood',[0,1.45,-.08],[.44,.45,.26],top);const mask=box(g,'mask',[0,1.58,.16],[.26,.11,.04],makeMat('#33323a'));}
 return {group:g,kind,speed:.7+Math.random()*.55,phase:Math.random()*6.28,home:new THREE.Vector3(x,0,z),caught:false};
}

import * as THREE from 'three';
import './style.css';
import {createWorld,createOfficer,createPerson,clamp} from './world.js';

const canvas=document.querySelector('#game'),hud=document.querySelector('#hud'),modalRoot=document.querySelector('#modal-root'),toast=document.querySelector('#toast');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
const scene=new THREE.Scene();const world=createWorld(scene);const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,220);const officer=createOfficer(scene);
const clock=new THREE.Clock();const keys={};let yaw=0,camPitch=.22,walking=0,elapsed=0,toastTimeout,nearby=null,modalOpen=false,lookDragging=false,lastX=0,lastY=0;
const player={pos:new THREE.Vector3(0,0,-1),emotion:18,wet:0,footHealth:100,shoe:'Babet',shoeType:'flats',tights:'Siyah ince',crimeCount:0,patrol:0,mission:0};
const missionList=[
 {name:'Mahalle devriyesi',desc:'Ana cadde ve sahil yolunda devriye gez. Şüpheli bir durum görürsen müdahale et.',target:3,progress:0},
 {name:'Kayıp çanta',desc:'Kırmızı montlu şüpheliyi bul ve güvenli biçimde durdur.',target:1,progress:0},
 {name:'Sahil güvenliği',desc:'Sahil yolundaki sivillerin yanına uğra, çevreyi kontrol et.',target:2,progress:0},
 {name:'Gece vardiyası',desc:'Devriye sırasında olaylara müdahale et ve vatandaşlara destek ol.',target:4,progress:0},
];let missionIndex=0,mission=missionList[missionIndex];
const criminals=[],civilians=[];const random=(a,b)=>a+Math.random()*(b-a);
const randomStreetPos=()=>{const lane=Math.random();if(lane<.45)return new THREE.Vector3(random(-4.5,4.5),0,random(-45,56));if(lane<.75)return new THREE.Vector3(random(-35,35),0,random(-17,-9));return new THREE.Vector3(random(-53,53),0,random(38,46));};
for(let i=0;i<14;i++){const p=randomStreetPos();civilians.push(createPerson(scene,p.x,p.z,'civilian',i))}
const spawnCriminal=(position)=>{let p=position;if(!p){p=randomStreetPos();if(p.distanceTo(player.pos)<15)p.x+=22}const bad=createPerson(scene,p.x,p.z,'criminal',criminals.length);bad.group.userData.crime=true;criminals.push(bad);return bad};
spawnCriminal(new THREE.Vector3(-15,0,-13));

function showToast(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toast.classList.remove('show'),2450)}
function setMissionProgress(amount=1){mission.progress=Math.min(mission.target,mission.progress+amount);if(mission.progress>=mission.target){player.patrol++;player.emotion=Math.max(0,player.emotion-8);showToast('Görev tamamlandı · Mahalle sana teşekkür ediyor ✨');setTimeout(()=>{missionIndex=(missionIndex+1)%missionList.length;mission=missionList[missionIndex];mission.progress=0;showToast('Yeni görev: '+mission.name)},1900)}}
function spawnEvent(){const events=[()=>{const p=spawnCriminal();showToast('🚨 Hırsızlık ihbarı! Şüpheli çevrede görüldü.');mission=missionList[1];mission.progress=0;missionIndex=1},()=>{const c=civilians[Math.floor(Math.random()*civilians.length)];c.group.position.x=clamp(c.group.position.x+random(-5,5),-55,55);showToast('📣 Bir vatandaş yardım istiyor. Yaklaş ve E ile konuş.');},()=>{showToast('🌧️ Sahilden rüzgâr ve ince yağmur geliyor… ayakkabıların ıslanabilir.');player.wet=Math.min(100,player.wet+17)},()=>{showToast('🚲 Sahil yolunda şüpheli bir hareketlilik var. Devriyeye devam et!');spawnCriminal(new THREE.Vector3(random(-5,5),0,random(37,44)))}];events[Math.floor(Math.random()*events.length)]()}
let nextEvent=19;

function renderHUD(){const pct=Math.min(100,player.emotion);const feet=player.footHealth<35?' · Ayakların hassas':player.wet>45?' · Islak':'';
hud.innerHTML=`<div class="topbar"><div class="brand"><div class="eyebrow">🌙 HAN RIVER DISTRICT · 21:40</div><div class="brand-title">SEOUL: Gece Devriyesi</div><div class="brand-sub">Memur Yuna Kim · Merkez Karakol</div></div><div class="top-right"><div class="panel emotion"><div class="stat-label">💗 Duygu durumu <span style="float:right">${player.emotion>75?'gözler doldu':player.emotion>48?'hassas':'iyi'}</span></div><div class="bar"><div class="bar-fill" style="width:${pct}%"></div></div><div style="font-size:9px;color:#8da0af;margin-top:5px">${Math.round(player.emotion)}% · sakin bir nefes al</div></div><div class="panel"><div class="stat-label">👞 Ayakkabı${feet}</div><div class="stat-val" style="font-size:13px">${player.shoe}</div><div class="bar"><div class="bar-fill" style="width:${player.footHealth}%;background:${player.footHealth<35?'#ed7786':'#85dfc2'}"></div></div></div><div class="panel"><div class="stat-label">₩ Bakiye</div><div class="stat-val" style="color:#f3ca70">∞ <small style="font-size:10px;color:#b9c3cf">sınırsız</small></div></div></div></div><div class="bottom-row"><div class="mission"><div class="mission-title">✦ Aktif görev · ${mission.progress}/${mission.target}</div><div class="mission-name">${mission.name}</div><div class="mission-desc">${mission.desc}</div></div><div class="bottom-hint"><span class="key">WASD</span> yürü <span class="key">Shift</span> koş &nbsp; <span class="key">E</span> etkileşim &nbsp; <span class="key">Q</span> kelepçele &nbsp; <span class="key">M</span> yardım</div><div class="right-bottom"><div class="interact-prompt" id="interact">E · Etkileşim</div><div style="font-size:10px;color:#f5f4eccc;text-shadow:0 2px 6px #000">${player.wet>50?'💧 Ayakkabıların sırılsıklam':player.footHealth<35?'🩹 Ayakların acıyor':'🌸 Duygularını koru, memur Yuna'}</div></div></div>`;
}
renderHUD();
function showModal(title,desc,body){if(modalOpen)return;modalOpen=true;modalRoot.innerHTML=`<div class="modal-root"><div class="modal-card"><div class="modal-head"><div><div class="eyebrow">SEOUL · DEVRIYE EKİPMANI</div><div class="modal-title">${title}</div><div class="modal-desc">${desc}</div></div><button class="close" id="closeModal">✕ Kapat</button></div>${body}</div></div>`;document.querySelector('#closeModal').onclick=closeModal;modalRoot.querySelector('.modal-root').onclick=e=>{if(e.target.classList.contains('modal-root'))closeModal()}}
function closeModal(){modalOpen=false;modalRoot.innerHTML=''}
const shoeCatalog=[
 ['Siyah şehir babeti','Babet','♧','#171820'],['Krem yumuşak babet','Babet','✿','#dbcaac'],['Gece mavisi babet','Babet','✦','#293951'],['Gül kurusu babet','Babet','❀','#ad717a'],['Beyaz kanvas babet','Babet','◇','#f2eee5'],['Yağmur geçirmez babet','Babet','☂','#334946'],['Klasik siyah stiletto','Stiletto','♢','#18171d'],['Bordo ince topuk','Stiletto','♦','#722f40'],['Gümüş gece topuğu','Stiletto','✧','#9da7b7'],['İnci beyazı topuk','Stiletto','✦','#ece8df'],['Kadife gece topuğu','Stiletto','❋','#473554'],['Karamel zarif topuk','Stiletto','♧','#956444'],['Kırmızı rugan stiletto','Stiletto','♥','#a63743'],['Altın davet topuğu','Stiletto','✧','#bb9858'],['Pudra pembe topuk','Stiletto','❀','#d99fa6'],['Gece göğü topuğu','Stiletto','✦','#384b76'],['Sahil platformu','Platform','☼','#bc855f'],['Retro blok topuk','Platform','▣','#7e634f'],['Zümrüt blok topuk','Platform','♧','#4a725e'],['Kent yürüyüş topuğu','Blok topuk','◈','#72585a'],['Kısa topuklu loafer','Loafer','▰','#553e33'],['Toka detaylı loafer','Loafer','♧','#534844'],['Saten gece babeti','Babet','✧','#917d99'],['İnce bantlı sandal','Sandalet','☼','#a86c55'],['Pudra bantlı sandal','Sandalet','❀','#ce9c9b'],['Siyah bilek botu','Bot','▰','#292a31'],['Kahve kısa bot','Bot','▰','#705744'],['Yağmur botu','Bot','☂','#526b69'],['Günlük spor babet','Babet','◇','#c5c6c1'],['Çiçek nakışlı babet','Babet','❀','#d9c8b3'],['Sedefli alçak topuk','Alçak topuk','✧','#c9bcaa'],['Lacivert klasik topuk','Stiletto','♦','#30415a'],['Şeftali ince topuk','Stiletto','❀','#dd9d7e'],['Kore sokak stili','Platform','★','#27252b'],['Gri yumuşak ev babeti','Babet','☁','#999ba1'],['Sahil kurtarma babeti','Babet','☂','#315a60']];
const tightsCatalog=[['Siyah ince','Siyah','rgba(19,22,32,.42)'],['Kömür mat','Mat kömür','rgba(30,34,41,.63)'],['Doğal ten','Ten','rgba(214,176,149,.38)'],['Fildişi opak','Beyaz','rgba(245,239,229,.86)'],['Bordo dikişli','Bordo','rgba(91,37,48,.62)'],['Lacivert klasik','Lacivert','rgba(35,51,78,.64)'],['Pudra şeffaf','Pudra','rgba(218,161,167,.4)'],['Gece parıltısı','Gece','rgba(57,57,79,.62)']];
function openShop(tab='shoes'){
 let active=tab;
 const draw=()=>{const products=active==='shoes'?shoeCatalog:tightsCatalog;const grid=products.map((item,i)=>{const isShoes=active==='shoes';const eq=isShoes?player.shoe===item[0]:player.tights===item[0];return `<div class="shop-item"><div class="shoe-icon" style="color:${isShoes?item[3]:'#e7d6ce'};text-shadow:0 1px 5px #fff5">${item[2]}</div><div class="item-name">${item[0]}</div><div class="item-info">${isShoes?item[1]:'Külotlu çorap'}</div><button class="shop-buy ${eq?'equipped':''}" data-i="${i}">${eq?'✓ Giyili':'₩ ∞ · Giy'}</button></div>`}).join('');return `<div class="tabs"><button class="tab ${active==='shoes'?'active':''}" data-tab="shoes">👠 Ayakkabılar · 36</button><button class="tab ${active==='tights'?'active':''}" data-tab="tights">🧦 Külotlu çorap · 8</button><button class="tab ${active==='shirt'?'active':''}" data-tab="shirt">👔 Üniforma</button></div>${active==='shirt'?`<div class="help-card"><strong>Resmî beyaz gömlek</strong><span>Temiz beyaz gömlek, lacivert polis üniforması ve rozet. Üniformanı düzenlemek için hazırsın.</span><br><button class="shop-buy" id="shirtEquip">✓ Beyaz gömlek giy</button></div>`:`<div class="shop-grid">${grid}</div>`}<div style="font-size:10px;color:#98a8b7;margin-top:13px">∞ Sınırsız görev bütçesi · Denemek için bir ürüne tıkla. Yüksek topukta uzun yürüyüş ayaklarını yorabilir.</div>`};
 showModal('Yuna’nın ayakkabı dükkânı','Seoul Station arka sokağı · Bütün ürünler görev bütçesinden karşılanır.',draw());
 const bind=()=>{modalRoot.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.tab;modalRoot.querySelector('.modal-card').innerHTML=`<div class="modal-head"><div><div class="eyebrow">SEOUL · DEVRIYE EKİPMANI</div><div class="modal-title">Yuna’nın ayakkabı dükkânı</div><div class="modal-desc">Seoul Station arka sokağı · Sınırsız görev bütçesi</div></div><button class="close" id="closeModal">✕ Kapat</button></div>${draw()}`;document.querySelector('#closeModal').onclick=closeModal;bind()});
 modalRoot.querySelectorAll('.shop-buy[data-i]').forEach(b=>b.onclick=()=>{const item=(active==='shoes'?shoeCatalog:tightsCatalog)[+b.dataset.i];if(active==='shoes'){player.shoe=item[0];player.shoeType=['Stiletto','Platform','Blok topuk'].includes(item[1])?'heels':['Bot'].includes(item[1])?'boots':item[1]==='Sandalet'?'sandals':'flats';player.footHealth=Math.min(100,player.footHealth+16);player.wet=Math.max(0,player.wet-45);officer.setShoes(player.shoeType);showToast('Yeni ayakkabın hazır ✨ Ayakların biraz rahatladı.')}else{player.tights=item[0];officer.setTights(item[2]);showToast(item[0]+' külotlu çorap giyildi ✨')}renderHUD();openShop(active)});
 const shirt=modalRoot.querySelector('#shirtEquip');if(shirt)shirt.onclick=()=>showToast('Beyaz gömleğin ve rozetin tertemiz görünüyor.');};bind();
}
function help(){showModal('Devriye not defteri','Yuna’nın şehir rehberi · Kontroller ve küçük ipuçları',`<div class="help-grid"><div class="help-card"><strong>⌨️ Hareket</strong><span><b>W A S D</b> ile yürü, <b>Shift</b> ile koş. Fareyi sürükleyerek kamerayı çevir. Telefonda ekrandaki yön tuşlarını kullan.</span></div><div class="help-card"><strong>🚨 Güvenli müdahale</strong><span>Şüpheliye yaklaş ve <b>Q</b> ile kelepçele. Silah yerine eğitimli polis müdahalesi ve telsiz kullanılır. <b>E</b> ile sivillerle konuş.</span></div><div class="help-card"><strong>👠 Ayakkabı bakımı</strong><span>Sahil kumunda ayakkabıların ıslanıp ağırlaşabilir. Dükkânda 36 ayakkabı ve 8 çorap modeli sınırsız bütçeyle deneyebilirsin. Uzun süre topuklu yürüyünce ayakların yorulur.</span></div><div class="help-card"><strong>💗 Hassas kalp</strong><span>Zor olaylar duygu seviyeni yükseltir. Görevleri tamamlamak ve vatandaşlara destek olmak sakinleşmene yardım eder. Çok yükselirse Yuna gözyaşlarına boğulur; biraz durup nefes al.</span></div><div class="help-card"><strong>📍 Şehri keşfet</strong><span>Altın işaretli dükkân caddenin güneyinde. Turkuaz işaret merkez karakolunu gösterir. Sahil doğu değil, mahallenin güney ucunda.</span></div><div class="help-card"><strong>🎯 Görev sistemi</strong><span>Aktif görevleri tamamla, devriye puanı kazan ve rastlantısal ihbarlara kulak ver. Her vardiyada yeni olaylar çıkar.</span></div></div>`)}

function interactionTarget(){let best=null,dist=Infinity;for(const c of criminals){if(c.caught)continue;const d=c.group.position.distanceTo(player.pos);if(d<dist){best={type:'criminal',obj:c,distance:d};dist=d}}for(const c of civilians){const d=c.group.position.distanceTo(player.pos);if(d<dist){best={type:'civilian',obj:c,distance:d};dist=d}}const shopDist=player.pos.distanceTo(new THREE.Vector3(15,0,8));if(shopDist<dist){best={type:'shop',distance:shopDist};dist=shopDist}return best}
function interact(){const target=interactionTarget();if(!target||target.distance>3.1){showToast('Yakında konuşabileceğin kimse yok.');return}if(target.type==='shop'){openShop();return}if(target.type==='criminal'){showToast('Şüpheliyi güvenli şekilde durdurmak için Q tuşuna bas.');return}player.emotion=Math.max(0,player.emotion-12);showToast(['Vatandaş: “Teşekkür ederim, memur hanım.” 💛','Vatandaş: “Mahallede kendimizi güvende hissediyoruz.”','Küçük bir iyilik, büyük bir fark 🌼'][Math.floor(Math.random()*3)]);setMissionProgress();renderHUD()}
function arrest(){let best=null,dist=4;for(const c of criminals){if(c.caught)continue;const d=c.group.position.distanceTo(player.pos);if(d<dist){best=c;dist=d}}if(!best){showToast('Kelepçe için bir şüpheliye yaklaşmalısın.');return}best.caught=true;best.group.visible=false;player.crimeCount++;player.emotion=Math.min(100,player.emotion+10);showToast('Şüpheli güvenli biçimde gözaltında. İyi iş, memur Kim! 🚓');setMissionProgress();setTimeout(()=>{if(Math.random()<.58)spawnCriminal()},7000);renderHUD()}
function playerMove(dt){let x=0,z=0;if(keys.KeyW||keys.ArrowUp)z-=1;if(keys.KeyS||keys.ArrowDown)z+=1;if(keys.KeyA||keys.ArrowLeft)x-=1;if(keys.KeyD||keys.ArrowRight)x+=1;const len=Math.hypot(x,z);if(len){x/=len;z/=len;const speed=(keys.ShiftLeft||keys.ShiftRight?6.2:3.5)*(player.footHealth<25?.7:1)*(player.wet>70?.83:1);const angle=yaw;const dx=x*Math.cos(angle)+z*Math.sin(angle),dz=-x*Math.sin(angle)+z*Math.cos(angle);player.pos.x=clamp(player.pos.x+dx*speed*dt,-65,65);player.pos.z=clamp(player.pos.z+dz*speed*dt,-58,78);officer.root.rotation.y=Math.atan2(dx,dz);walking=speed; if(player.shoeType==='heels'){player.footHealth=Math.max(0,player.footHealth-dt*.42*(speed>4?1.5:1));if(player.footHealth===0){player.shoe='Yalın ayak';player.shoeType='barefoot';officer.setShoes('barefoot');showToast('Ayakların çok yoruldu… ayakkabılarını çıkardın. Dükkâna uğra!');player.footHealth=10}}if(player.pos.z>57&&player.shoeType!=='boots'){player.wet=Math.min(100,player.wet+dt*2);if(player.wet>80&&player.shoeType==='flats'&&player.shoe!=='Islak babet'){player.shoe='Islak babet';showToast('Deniz suyu babetlerini ıslattı. Dükkânda yedek ayakkabı var!')}}if(player.pos.z<50)player.wet=Math.max(0,player.wet-dt*.5);
 }else walking=0;
 // emotion rises with time and occasional incidents; staying still lets her breathe
 if(walking===0)player.emotion=Math.max(8,player.emotion-dt*1.1);else player.emotion=Math.min(100,player.emotion+dt*.11);
 if(player.emotion>=99&&!officer.head.userData.crying){officer.head.userData.crying=true;showToast('Yuna’nın gözleri doldu… Bir an durup nefes alıyor. 🥺');}if(player.emotion<70)officer.head.userData.crying=false;
 officer.root.position.copy(player.pos);officer.updateWalk(elapsed,walking);
}
function updatePeople(dt){for(const c of civilians){if(c.group.position.distanceTo(player.pos)<7)c.group.rotation.y+=Math.sin(elapsed*2+c.phase)*dt*.7;else{c.group.position.x+=Math.sin(elapsed*.3+c.phase)*dt*.15;c.group.position.z+=Math.cos(elapsed*.4+c.phase)*dt*.15}c.group.position.x=clamp(c.group.position.x,-60,60);c.group.position.z=clamp(c.group.position.z,-55,73)}for(const c of criminals){if(c.caught)continue;const d=c.group.position.distanceTo(player.pos);if(d<8){const away=c.group.position.clone().sub(player.pos).setY(0).normalize();c.group.position.addScaledVector(away,c.speed*dt*1.5);c.group.rotation.y=Math.atan2(away.x,away.z)}else{c.group.position.x+=Math.sin(elapsed*.7+c.phase)*dt*.2;c.group.position.z+=Math.cos(elapsed*.55+c.phase)*dt*.2}}}
function updateCamera(dt){const target=player.pos.clone().add(new THREE.Vector3(0,1.45,0));const distance=7.8;const horizontal=Math.cos(camPitch)*distance;const desired=new THREE.Vector3(target.x+Math.sin(yaw)*horizontal,target.y+Math.sin(camPitch)*distance+1.05,target.z+Math.cos(yaw)*horizontal);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(target)}
function renderMinimap(){let el=document.querySelector('#minimap');if(!el){const c=document.createElement('canvas');c.id='minimap';c.width=150;c.height=150;c.style.cssText='position:fixed;right:24px;top:106px;width:132px;height:132px;border-radius:50%;border:1px solid #ffffff55;box-shadow:0 4px 18px #0006;pointer-events:none;background:#13212caa';document.body.append(c);el=c}const ctx=el.getContext('2d');const w=150;ctx.clearRect(0,0,w,w);ctx.save();ctx.beginPath();ctx.arc(75,75,73,0,Math.PI*2);ctx.clip();ctx.fillStyle='#263a3e';ctx.fillRect(0,0,w,w);ctx.fillStyle='#525963';ctx.fillRect(68,0,15,150);ctx.fillRect(0,58,150,12);ctx.fillRect(0,112,150,8);ctx.fillStyle='#b8ad92';ctx.fillRect(45,0,4,150);ctx.fillRect(100,0,4,150);ctx.fillStyle='#507b7e';ctx.fillRect(0,132,150,20);ctx.fillStyle='#819782';ctx.fillRect(40,0,6,150);ctx.fillRect(105,0,6,150);const px=75+player.pos.x*1.18,pz=75+player.pos.z*1.05;ctx.fillStyle='#f0c86c';ctx.beginPath();ctx.arc(75+15*1.18,75+8*1.05,4,0,7);ctx.fill();ctx.fillStyle='#61dfbb';ctx.beginPath();ctx.arc(px,pz,5,0,7);ctx.fill();ctx.strokeStyle='#c9f4e6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px,pz);ctx.lineTo(px+Math.sin(officer.root.rotation.y)*10,pz+Math.cos(officer.root.rotation.y)*10);ctx.stroke();for(const c of criminals){if(!c.caught){ctx.fillStyle='#f17e80';ctx.fillRect(75+c.group.position.x*1.18-2,75+c.group.position.z*1.05-2,4,4)}}ctx.restore();}
let hudTimer=0;
function animate(){requestAnimationFrame(animate);const dt=Math.min(.04,clock.getDelta());elapsed+=dt;if(!modalOpen)playerMove(dt);updatePeople(dt);updateCamera(dt);world.update(elapsed);const target=interactionTarget();nearby=target;const prompt=document.querySelector('#interact');if(prompt){prompt.classList.toggle('show',!!target&&target.distance<3.1);if(target&&target.distance<3.1)prompt.textContent=target.type==='shop'?'E · Ayakkabı dükkânı':target.type==='criminal'?'Q · Şüpheliyi durdur':'E · Vatandaşla konuş'}hudTimer+=dt;if(hudTimer>.12){renderHUD();renderMinimap();hudTimer=0}if(elapsed>nextEvent){spawnEvent();nextEvent=elapsed+random(22,38)}renderer.render(scene,camera)}animate();

addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyQ')arrest();if(e.code==='KeyM')help();if(e.code==='Escape'&&modalOpen)closeModal();if(e.code==='KeyH')openShop()});addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointerdown',e=>{if(e.button===0){lookDragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointerup',()=>lookDragging=false);canvas.addEventListener('pointermove',e=>{if(!lookDragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;yaw-=dx*.006;camPitch=clamp(camPitch+dy*.002,-.12,.8)});canvas.addEventListener('wheel',e=>{camera.fov=clamp(camera.fov+e.deltaY*.025,42,70);camera.updateProjectionMatrix()},{passive:true});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
// touch controls
const controls=document.createElement('div');controls.className='mobile-controls';controls.innerHTML=`<div class="dpad"><button class="touch-btn" style="grid-column:2;grid-row:1" data-key="KeyW">▲</button><button class="touch-btn" style="grid-column:1;grid-row:2" data-key="KeyA">◀</button><button class="touch-btn" style="grid-column:2;grid-row:2" data-key="KeyS">▼</button><button class="touch-btn" style="grid-column:3;grid-row:2" data-key="KeyD">▶</button></div><div class="touch-actions"><button class="touch-btn" id="touchHelp">?</button><button class="touch-btn" id="touchRun">KOŞ</button><button class="touch-btn" id="touchTalk">E<br>ETKİ</button><button class="touch-btn primary" id="touchArrest">Q<br>POLİS</button></div>`;document.body.append(controls);controls.querySelectorAll('[data-key]').forEach(b=>{const key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;b.setPointerCapture(e.pointerId)});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>keys[key]=false)});const run=controls.querySelector('#touchRun');run.onpointerdown=e=>{e.preventDefault();keys.ShiftLeft=true};for(const ev of ['pointerup','pointercancel','lostpointercapture'])run.addEventListener(ev,()=>keys.ShiftLeft=false);controls.querySelector('#touchTalk').onclick=interact;controls.querySelector('#touchArrest').onclick=arrest;controls.querySelector('#touchHelp').onclick=help;
setTimeout(()=>showToast('Devriye başladı, memur Kim. Şehri keşfetmek için WASD kullan. 👮🏻‍♀️'),900);

